CREATE TYPE tx_status AS ENUM ('PENDING','COMPLETED','FAILED','HELD','REVERSED'); CREATE TYPE entry_dir AS ENUM ('DEBIT','CREDIT');
CREATE TABLE users ( id BIGSERIAL PRIMARY KEY, email TEXT NOT NULL UNIQUE, api_key_hash TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE accounts ( id BIGSERIAL PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id), currency CHAR(3) NOT NULL DEFAULT 'INR', balance NUMERIC(18,2) NOT NULL DEFAULT 0, version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), CONSTRAINT balance_non_negative CHECK (balance >= 0) );
CREATE TABLE transactions ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), idempotency_key TEXT NOT NULL, source_account BIGINT NOT NULL REFERENCES accounts(id), dest_account BIGINT NOT NULL REFERENCES accounts(id), amount NUMERIC(18,2) NOT NULL CHECK (amount > 0), currency CHAR(3) NOT NULL, status tx_status NOT NULL DEFAULT 'PENDING', failure_reason TEXT, request_hash TEXT NOT NULL, response_body JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), CONSTRAINT uq_idem UNIQUE (idempotency_key) ); CREATE INDEX idx_tx_source_created ON transactions (source_account, created_at DESC);
CREATE TABLE ledger_entries ( id BIGSERIAL PRIMARY KEY, transaction_id UUID NOT NULL REFERENCES transactions(id), account_id BIGINT NOT NULL REFERENCES accounts(id), direction entry_dir NOT NULL, amount NUMERIC(18,2) NOT NULL CHECK (amount > 0), created_at TIMESTAMPTZ NOT NULL DEFAULT now() ); CREATE INDEX idx_ledger_account ON ledger_entries (account_id, id);